-- ============================================================
-- WAWE JOURNAL - Backtest candle archive (private Storage bucket "candles")
-- Migration: <NNNN>_candles_storage_bucket.sql   (final number assigned by the plan)
--
-- Objects: <SYMBOL>/<YYYY-MM>.json.gz (1m candles, UTC) and <SYMBOL>/index.json.
-- * Signed-in users (role authenticated) may only DOWNLOAD objects of this bucket
--   (sb.storage.from('candles').download(...)): no listing, no signed URLs, no upload/overwrite/delete.
-- * anon gets nothing. Writes: only the scripts/ importer with the secret / service_role key (BYPASSRLS).
-- * Dukascopy / Binance data: this bucket must NEVER be made public.
-- * Do not add "alter table storage.objects ...": storage tables belong to supabase_storage_admin
--   (ERROR 42501 must be owner). RLS is already enabled; policies can be managed with SQL.
-- * Requires storage.allow_any_operation(text[]) (Storage tenant migration 0058, 2026-03-27).
-- * Policy names follow avatars_select_own (202608190001_security_baseline.sql:175-187).
-- Rollback: <NNNN>_candles_storage_bucket.down.sql (objects must first be deleted via the Storage API).
-- ============================================================

begin;

do $$
begin
  if to_regprocedure('storage.allow_any_operation(text[])') is null then
    raise exception 'storage.allow_any_operation(text[]) is missing (Storage older than tenant migration 0058). Use the fallback policy from the plan.';
  end if;
end
$$;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('candles', 'candles', false, 5242880, array['application/gzip', 'application/json'])
on conflict (id) do update
  set public             = false,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "candles_select_authenticated"       on storage.objects;
drop policy if exists "candles_guard_select_anon"          on storage.objects;
drop policy if exists "candles_guard_select_authenticated" on storage.objects;
drop policy if exists "candles_guard_insert"               on storage.objects;
drop policy if exists "candles_guard_update"               on storage.objects;
drop policy if exists "candles_guard_delete"               on storage.objects;

-- The only grant: signed-in users may download
-- (GET /storage/v1/object/[authenticated/]candles/<path> = operation storage.object.get_authenticated).
create policy "candles_select_authenticated" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'candles'
    and storage.allow_any_operation(array['object.get_authenticated'])
  );

-- Guard rails. RESTRICTIVE policies are AND-ed with every permissive policy, so an older broad policy
-- (e.g. one created in the dashboard for bug-reports / references-images without a bucket_id filter;
-- those policies are not in the repo) can never open this bucket to anon reads, listing, signed URLs
-- or client writes. Other buckets are unaffected: for them "bucket_id is distinct from 'candles'" is true.
create policy "candles_guard_select_anon" on storage.objects
  as restrictive for select to anon
  using (bucket_id is distinct from 'candles');

create policy "candles_guard_select_authenticated" on storage.objects
  as restrictive for select to authenticated
  using (
    bucket_id is distinct from 'candles'
    or storage.allow_any_operation(array['object.get_authenticated'])
  );

create policy "candles_guard_insert" on storage.objects
  as restrictive for insert to anon, authenticated
  with check (bucket_id is distinct from 'candles');

create policy "candles_guard_update" on storage.objects
  as restrictive for update to anon, authenticated
  using (bucket_id is distinct from 'candles')
  with check (bucket_id is distinct from 'candles');

create policy "candles_guard_delete" on storage.objects
  as restrictive for delete to anon, authenticated
  using (bucket_id is distinct from 'candles');

commit;

-- ---------- Verification (read-only, run by the owner after applying) ----------
-- select id, public, file_size_limit, allowed_mime_types from storage.buckets where id = 'candles';
-- select policyname, permissive, roles, cmd from pg_policies
--  where schemaname = 'storage' and tablename = 'objects' and policyname like 'candles%' order by policyname;
-- Broad legacy policies that the guards protect against (review them):
-- select policyname, permissive, roles, cmd, qual, with_check from pg_policies
--  where schemaname = 'storage' and tablename = 'objects' and permissive = 'PERMISSIVE'
--    and coalesce(qual, '') || coalesce(with_check, '') not like '%bucket_id%';
--
-- ---------- HTTP smoke test after deploy (owner) ----------
-- 1) apikey only (anon), GET /storage/v1/object/candles/EURUSD/index.json -> HTTP 400 {"statusCode":"404",...}
-- 2) the same with Authorization: Bearer <user JWT> -> 200
-- 3) user JWT, POST /storage/v1/object/list/candles {"prefix":"EURUSD"} -> []
-- 4) user JWT, POST /storage/v1/object/sign/candles/EURUSD/index.json {"expiresIn":60} -> 400 not found
-- 5) user JWT, POST /storage/v1/object/candles/EURUSD/x.json.gz -> rejected by RLS
--
-- ---------- Fallback, only if the helper is missing ----------
-- Weaker: signed-in users could also list the bucket and mint signed URLs.
-- Replace the select policy with the line below and omit "candles_guard_select_authenticated":
-- create policy "candles_select_authenticated" on storage.objects for select to authenticated using (bucket_id = 'candles');
--
-- Evidence:
-- * Operation helpers: supabase/storage migrations/tenant/0058-operation-ergonomics.sql
--   and docs guides/storage/schema/helper-functions.mdx.
-- * Operation names: supabase/storage src/http/routes/operations.ts.
-- * download() uses GET_AUTH_OBJECT: src/http/routes/object/getObject.ts.
-- * Docs example with allow_any_operation: guides/storage/security/access-control.mdx:88-99.
-- * Policies stay SQL-manageable: https://supabase.com/changelog/9314-security-patch-notice
-- * The 42501 risk is the repo's own line supabase/migrations/202608190001_security_baseline.sql:170.

bucketRollbackSql:
-- ============================================================
-- WAWE JOURNAL - ROLLBACK of <NNNN>_candles_storage_bucket.sql
--
-- STEP 1 (required, NOT SQL): delete every object of bucket "candles" through the Storage API with the
-- secret/service_role key. SQL cannot do it:
--   * storage.protect_delete() (Storage tenant migration 0055, 2026-01-28) is a BEFORE DELETE ... FOR EACH STATEMENT
--     trigger on storage.objects AND storage.buckets. It raises 'Direct deletion from storage tables is not allowed.
--     Use the Storage API instead.' unless storage.allow_delete_query = 'true'.
--   * The docs also say a SQL delete leaves the file orphaned in the bucket's object store
--     (guides/storage/management/delete-objects.mdx).
--   Options:
--   a) Importer purge mode. It lists <SYMBOL>/ for every configured symbol
--      (POST /storage/v1/object/list/candles {"prefix":"EURUSD","limit":1000,"offset":0}).
--      It then deletes in batches of <= 1000 (DELETE /storage/v1/object/candles {"prefixes":["EURUSD/2020-01.json.gz", ...]}).
--      This is synchronous.
--   b) Dashboard > Storage > candles > Empty bucket. This is queued: "Completion may take up to an hour"
--      (storage src/http/routes/bucket/emptyBucket.ts). Wait until this returns 0:
--        select count(*) from storage.objects where bucket_id = 'candles';
--   Optional: delete the bucket itself there (Dashboard "Delete bucket" or DELETE /storage/v1/bucket/candles;
--   the API refuses with BucketNotEmpty while objects remain). Step 2 removes the row if it still exists.
-- STEP 2: run this file. It aborts while any object is left.
-- ============================================================

begin;

do $$
declare
  v_left bigint;
begin
  select count(*) into v_left from storage.objects where bucket_id = 'candles';
  if v_left > 0 then
    raise exception 'Bucket "candles" still holds % object(s). Empty it through the Storage API first (step 1).', v_left;
  end if;
end
$$;

drop policy if exists "candles_select_authenticated"       on storage.objects;
drop policy if exists "candles_guard_select_anon"          on storage.objects;
drop policy if exists "candles_guard_select_authenticated" on storage.objects;
drop policy if exists "candles_guard_insert"               on storage.objects;
drop policy if exists "candles_guard_update"               on storage.objects;
drop policy if exists "candles_guard_delete"               on storage.objects;

-- Remove the now-empty bucket row if step 1 did not delete it.
-- storage.protect_delete() lets a DELETE through only when storage.allow_delete_query = 'true'
-- (the Storage API sets the same flag). It is set for this transaction only. Nothing can be orphaned
-- because the bucket was verified empty above.
-- If this fails with a foreign-key error (e.g. a stale multipart upload row), delete the bucket via
-- the Dashboard or DELETE /storage/v1/bucket/candles and re-run this file.
do $$
begin
  if exists (select 1 from storage.buckets where id = 'candles') then
    perform set_config('storage.allow_delete_query', 'true', true);
    delete from storage.buckets where id = 'candles';
  end if;
end
$$;

commit;

-- Check (read-only): both must return 0 rows
-- select id from storage.buckets where id = 'candles';
-- select policyname from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'candles%';
-- Client side (optional): browsers keep cached months in IndexedDB "ww-candles"; the page can call
-- indexedDB.deleteDatabase('ww-candles') when the feature is removed.
-- Evidence: supabase/storage migrations/tenant/0055-prevent-direct-deletes.sql;
--   src/storage/storage.ts deleteBucket (BucketNotEmpty) and emptyBucket.
